audits=[];variants=[];queue=[];own_pids=[]
for qid,vid,finals in VARIANTS:
    out=HERE/qid/vid;plugin=json.loads((out/'plugin.json').read_text(encoding='utf-8'));design=json.loads((out/'design.json').read_text(encoding='utf-8'));render=json.loads((out/'render_check.json').read_text(encoding='utf-8'))
