        proc=json.loads((out/'api_process.json').read_text(encoding='utf-8'));own_pids.append(proc['pid']);assert (out/'api_process_finished.json').exists()
        variant.update(status=status,complete_pair=True,completed_calls=2,manual_finals=finals,target_hit_count=sum(r['predeclared_target_hit'] for r in manual),raw_evidence_directory=str(evidence.relative_to(ROOT)),binding_path=str((evidence/'binding.json').relative_to(ROOT)),manual_final_review_path=str((out/'manual_final_review.json').relative_to(ROOT)),limitations=limitations)
